sctp_common_input_processing(struct mbuf **mm, int iphlen, int offset, int length,
                             struct sockaddr *src, struct sockaddr *dst,
                             struct sctphdr *sh, struct sctp_chunkhdr *ch,
                             uint8_t compute_crc,
                             uint8_t ecn_bits,
#if defined(__FreeBSD__)
                             uint8_t mflowtype, uint32_t mflowid, uint16_t fibnum,
#endif
                             uint32_t vrf_id, uint16_t port)
{
        uint32_t high_tsn;
        int fwd_tsn_seen = 0, data_processed = 0;
        struct mbuf *m = *mm, *op_err;
        char msg[SCTP_DIAG_INFO_LEN];
        int un_sent;
        int cnt_ctrl_ready = 0;
        struct sctp_inpcb *inp = NULL, *inp_decr = NULL;
        struct sctp_tcb *stcb = NULL;
        struct sctp_nets *net = NULL;
#if defined(__Userspace__)
        struct socket *upcall_socket = NULL;
#endif

        SCTP_STAT_INCR(sctps_recvdatagrams);
#ifdef SCTP_AUDITING_ENABLED
        sctp_audit_log(0xE0, 1);
        sctp_auditing(0, inp, stcb, net);
#endif
        if (compute_crc != 0) {
                uint32_t check, calc_check;

                check = sh->checksum;
                sh->checksum = 0;
                calc_check = sctp_calculate_cksum(m, iphlen);
                sh->checksum = check;
                if (calc_check != check) {
                        SCTPDBG(SCTP_DEBUG_INPUT1, "Bad CSUM on SCTP packet calc_check:%x check:%x  m:%p mlen:%d iphlen:%d\n",
                                calc_check, check, (void *)m, length, iphlen);
                        stcb = sctp_findassociation_addr(m, offset, src, dst,
                                                         sh, ch, &inp, &net, vrf_id);
#if defined(INET) || defined(INET6)
                        if ((ch->chunk_type != SCTP_INITIATION) &&
                            (net != NULL) && (net->port != port)) {
                                if (net->port == 0) {
                                        /* UDP encapsulation turned on. */
                                        net->mtu -= sizeof(struct udphdr);
                                        if (stcb->asoc.smallest_mtu > net->mtu) {
                                                sctp_pathmtu_adjustment(stcb, net->mtu);
                                        }
                                } else if (port == 0) {
                                        /* UDP encapsulation turned off. */
                                        net->mtu += sizeof(struct udphdr);
                                        /* XXX Update smallest_mtu */
                                }
                                net->port = port;
                        }
#endif
#if defined(__FreeBSD__)
                        if (net != NULL) {
                                net->flowtype = mflowtype;
                                net->flowid = mflowid;
                        }
                        SCTP_PROBE5(receive, NULL, stcb, m, stcb, sh);
#endif
                        if ((inp != NULL) && (stcb != NULL)) {
                                sctp_send_packet_dropped(stcb, net, m, length, iphlen, 1);
                                sctp_chunk_output(inp, stcb, SCTP_OUTPUT_FROM_INPUT_ERROR, SCTP_SO_NOT_LOCKED);
                        } else if ((inp != NULL) && (stcb == NULL)) {
                                inp_decr = inp;
                        }
                        SCTP_STAT_INCR(sctps_badsum);
                        SCTP_STAT_INCR_COUNTER32(sctps_checksumerrors);
                        goto out;
                }
        }
        /* Destination port of 0 is illegal, based on RFC4960. */
        if (sh->dest_port == 0) {
                SCTP_STAT_INCR(sctps_hdrops);
                goto out;
        }
        stcb = sctp_findassociation_addr(m, offset, src, dst,
                                         sh, ch, &inp, &net, vrf_id);
#if defined(INET) || defined(INET6)
        if ((ch->chunk_type != SCTP_INITIATION) &&
            (net != NULL) && (net->port != port)) {
                if (net->port == 0) {
                        /* UDP encapsulation turned on. */
                        net->mtu -= sizeof(struct udphdr);
                        if (stcb->asoc.smallest_mtu > net->mtu) {
                                sctp_pathmtu_adjustment(stcb, net->mtu);
                        }
                } else if (port == 0) {
                        /* UDP encapsulation turned off. */
                        net->mtu += sizeof(struct udphdr);
                        /* XXX Update smallest_mtu */
                }
                net->port = port;
        }
#endif
#if defined(__FreeBSD__)
        if (net != NULL) {
                net->flowtype = mflowtype;
                net->flowid = mflowid;
        }
#endif
        if (inp == NULL) {
#if defined(__FreeBSD__)
                SCTP_PROBE5(receive, NULL, stcb, m, stcb, sh);
#endif
                SCTP_STAT_INCR(sctps_noport);
#if defined(__FreeBSD__) && (((__FreeBSD_version < 900000) && (__FreeBSD_version >= 804000)) || (__FreeBSD_version > 900000))
                if (badport_bandlim(BANDLIM_SCTP_OOTB) < 0) {
                        goto out;
                }
#endif
                if (ch->chunk_type == SCTP_SHUTDOWN_ACK) {
                        sctp_send_shutdown_complete2(src, dst, sh,
#if defined(__FreeBSD__)
                                                     mflowtype, mflowid, fibnum,
#endif
                                                     vrf_id, port);
                        goto out;
                }
                if (ch->chunk_type == SCTP_SHUTDOWN_COMPLETE) {
                        goto out;
                }
                if (ch->chunk_type != SCTP_ABORT_ASSOCIATION) {
                        if ((SCTP_BASE_SYSCTL(sctp_blackhole) == 0) ||
                            ((SCTP_BASE_SYSCTL(sctp_blackhole) == 1) &&
                             (ch->chunk_type != SCTP_INIT))) {
                                op_err = sctp_generate_cause(SCTP_BASE_SYSCTL(sctp_diag_info_code),
                                                             "Out of the blue");
                                sctp_send_abort(m, iphlen, src, dst,
                                                sh, 0, op_err,
#if defined(__FreeBSD__)
                                                mflowtype, mflowid, fibnum,
#endif
                                                vrf_id, port);
                        }
                }
                goto out;
